insert into tasks (id, week, sort_order, title, note, detail, done) values
('w1-01', 1, 1, 'Cambiar el titular de LinkedIn', 'Opción A: Creator & Influencer Marketing | Negociación con creadores y managers | Campañas para Rexona, PepsiCo, Knorr y DiDi', '[{"t": "p", "text": "El titular es lo primero que ve un recruiter en una búsqueda. Los nombres de marca hacen el trabajo pesado."}, {"items": ["Abrí tu perfil de LinkedIn y tocá el lápiz junto a tu nombre.", "Reemplazá el titular por el texto de abajo.", "Guardá."], "t": "steps"}, {"label": "Titular", "t": "copy", "text": "Creator & Influencer Marketing | Negociación con creadores y managers | Campañas para Rexona, PepsiCo, Knorr y DiDi"}]'::jsonb, false),
('w1-02', 1, 2, 'Elegir el "Acerca de" y subirlo a LinkedIn', 'Opción 1 o 2; leerlas en voz alta y quedarse con la que suene natural', '[{"t": "p", "text": "Leé las dos en voz alta y quedate con la que te salga natural. Lo que pongas acá lo vas a tener que sostener en una entrevista."}, {"label": "Opción 1 · con voz propia", "t": "copy", "text": "Negocio con creadores para que las marcas inviertan mejor.\n\nHace más de 3 años trabajo en Creator & Influencer Marketing para marcas como Rexona, Knorr, Magnum, PepsiCo y DiDi. Armo escenarios a partir del presupuesto, selecciono talentos con datos (ER, CPV, CPI, audiencias) y negocio directamente con creadores y managers.\n\nMi diferencial está en la mesa de negociación: cierro por debajo de lo cotizado, con ahorros de hasta 24%, en escenarios de hasta USD 300K. Y después acompaño la campaña: reviso guiones, alineo contenidos a la marca y sostengo la relación con el talento hasta el final.\n\nMe interesan los proyectos desafiantes, las marcas con cultura propia y los equipos donde la creatividad y los números conviven."}, {"label": "Opción 2 · más corporativa", "t": "copy", "text": "Especialista en Creator & Influencer Marketing con más de 3 años de experiencia en campañas para marcas de consumo masivo como Rexona, Knorr, Magnum, PepsiCo y DiDi.\n\nGestiono campañas de punta a punta: construcción de escenarios según presupuesto, selección de talentos basada en datos (ER, CPV, CPI, demografía), negociación con creadores y managers, contratación y supervisión de contenidos.\n\nFuerte perfil comercial: genero ahorros de hasta 24% frente a cotizaciones iniciales en escenarios de hasta USD 300K, y sostengo relaciones de largo plazo con talentos y representantes.\n\nParticipé en más de 50 proyectos, incluyendo la campaña de Rexona Men durante el Mundial y lanzamientos de PepsiCo."}, {"items": ["En tu perfil, buscá la sección \"Acerca de\" y tocá el lápiz.", "Pegá la opción elegida.", "Revisá que la primera línea se vea completa antes del \"ver más\"."], "t": "steps"}]'::jsonb, false),
('w1-03', 1, 3, 'Activar "Open to Work" solo para recruiters', 'Sin el marco verde en la foto', '[{"t": "p", "text": "Así aparecés en las búsquedas de recruiters sin que se vea en tu perfil público. Thinky no lo ve, salvo que un recruiter de Thinky te busque."}, {"items": ["En tu perfil, tocá \"Abierto a\" y elegí \"Buscar empleo nuevo\".", "Puestos: Influencer Marketing Specialist, Creator Partnerships, Brand Partnerships, Marketing Specialist.", "Ubicación: Buenos Aires y remoto.", "En visibilidad elegí \"Solo selectores de personal\". Nunca \"Todos los miembros de LinkedIn\": eso agrega el marco verde a la foto."], "t": "steps"}]'::jsonb, false),
('w1-04', 1, 4, 'Revisar y validar el CV versión marca', 'Marcar lo que no le suene propio', '[{"t": "p", "text": "Karen te pasó el CV en PDF y en Word. Leelo con calma y marcá todo lo que no sea exacto o no te suene propio."}, {"items": ["Que cada número sea real: 24%, USD 300K, más de 50 campañas.", "Que las marcas y campañas estén bien nombradas.", "Que puedas explicar cada línea en una entrevista.", "El nivel de inglés se actualiza después del EF SET."], "t": "list"}, {"t": "p", "text": "Mandale a Karen los cambios en un mensaje, no edites el archivo vos."}]'::jsonb, false),
('w1-05', 1, 5, 'Hacer el EF SET', 'Test gratuito; guardar el certificado con link', '[{"t": "p", "text": "Es gratis, online, y te da un nivel de A1 a C2 con certificado y link para sumar al CV y a LinkedIn."}, {"items": ["Entrá a efset.org y elegí el test completo (unos 50 minutos).", "Hacelo con auriculares, en un lugar sin interrupciones.", "Guardá el link del certificado y pasáselo a Karen."], "t": "steps"}]'::jsonb, false),
('w2-01', 2, 1, 'Actualizar el nivel de inglés en CV y LinkedIn', 'Con el resultado del EF SET, ej.: Inglés C1 (EF SET)', '[{"t": "p", "text": "Un nivel certificado pesa mucho más que \"intermedio / avanzado\"."}, {"label": "Cómo queda en el CV", "t": "copy", "text": "Inglés C1 (EF SET)"}, {"items": ["Cambiá C1 por tu nivel real.", "En LinkedIn, sumalo en \"Licencias y certificaciones\" con el link del certificado.", "Actualizalo también en la sección Idiomas."], "t": "steps"}, {"t": "p", "text": "Si da por debajo de B2, avisale a Karen: el inglés pasa a ser un frente a trabajar en paralelo."}]'::jsonb, false),
('w2-02', 2, 2, 'Decidir si acepta la puerta lateral', 'Agencia local que maneja cuentas de las marcas objetivo, como paso intermedio', '[{"t": "p", "text": "Las marcas grandes muchas veces tercerizan el influencer marketing en agencias. Entrar a la agencia local que maneja la cuenta de Unilever o Coca-Cola es trabajar con esas marcas, en blanco y en horario argentino."}, {"items": ["A favor: encajás casi 1 a 1, el ingreso es más rápido y el salto a la marca después es más corto.", "En contra: puede sentirse como no haberte movido del rol de agencia."], "t": "list"}, {"t": "p", "text": "No hay respuesta correcta. Contale a Karen qué sentís y se ajusta el mapa."}]'::jsonb, false),
('w2-03', 2, 3, 'Armar el CV versión agencia', 'Solo si la puerta lateral entra en el plan', '[{"t": "p", "text": "Solo si decidiste que la puerta lateral entra en el plan. A una agencia le importa el margen y la operación; a una marca, el presupuesto que rinde más."}, {"t": "p", "text": "Karen lo arma con Claude a partir de la versión marca. Vos solo lo validás como hiciste con el primero."}]'::jsonb, false),
('w2-04', 2, 4, 'Pedir 2 recomendaciones en LinkedIn', 'A compañeros o managers con los que haya cerrado campañas', '[{"t": "p", "text": "Dos recomendaciones de gente que te vio negociar o cerrar campañas valen más que cualquier línea del perfil."}, {"items": ["Alguien de cuentas con quien hayas trabajado mucho.", "Un manager o representante de creadores con quien tengas buena relación.", "Un líder o ex líder tuyo."], "t": "list"}, {"label": "Mensaje para pedirla", "t": "copy", "text": "Hola [nombre], ¿cómo estás? Estoy actualizando mi perfil de LinkedIn y me encantaría tener una recomendación tuya sobre cómo trabajamos juntos en [campaña o marca]. Si te queda cómodo, mencionar la parte de negociación me sumaría mucho. ¡Gracias!"}]'::jsonb, false),
('w3-01', 3, 1, 'Armar la lista de 20 empresas objetivo', 'Marcas (Unilever, Mercado Libre, Red Bull…) y agencias locales con buenas cuentas', '[{"t": "p", "text": "Veinte empresas concretas, no categorías. Este mapa define a quién le vas a escribir las próximas cinco semanas."}, {"items": ["Unas 8 marcas, empezando por las que ya conocés desde adentro: Unilever, PepsiCo, Mercado Libre, Red Bull, Coca-Cola.", "Unas 8 agencias locales que manejen cuentas de esas marcas.", "Unas 4 empresas con equipos internos de marketing grandes y horario argentino."], "t": "list"}, {"t": "p", "text": "Pasale la lista a Karen: ella la carga en el tablero con Claude."}]'::jsonb, false),
('w3-02', 3, 2, 'Identificar quién maneja influencer marketing en cada una', 'Nombre y rol en LinkedIn; cargarlos en Contactos', '[{"items": ["En LinkedIn, buscá personas con el nombre de la empresa más: Influencer Marketing, Brand Manager, Social Media Lead, Head of Marketing.", "Por empresa, quedate con 1 o 2 personas que decidan o trabajen cerca de creadores.", "Cargalas en Contactos con nombre, empresa y rol. El estado arranca en \"Por contactar\"."], "t": "steps"}]'::jsonb, false),
('w3-03', 3, 3, 'Cargar las primeras 10 en Postulaciones como "Identificada"', null, '[{"items": ["Abrí la pestaña Postulaciones.", "Completá empresa y puesto (si hay una búsqueda abierta, pegá el link).", "Dejá la etapa en \"Identificada\" y tocá Agregar."], "t": "steps"}, {"t": "p", "text": "\"Identificada\" es una empresa a la que vas a apuntar, aunque todavía no haya una búsqueda publicada."}]'::jsonb, false),
('w4-01', 4, 1, 'Escribirle a 5 personas del mapa', 'Mensaje corto: quién es, qué hace, por qué esa empresa', '[{"items": ["Elegí 5 personas de Contactos que estén en \"Por contactar\".", "Mandales solicitud de conexión en LinkedIn con una nota (máximo 300 caracteres).", "Cambiá su estado a \"Contactado\" en el tablero."], "t": "steps"}, {"label": "Nota de conexión", "t": "copy", "text": "Hola [nombre], trabajo en influencer marketing para marcas como Rexona y PepsiCo, negociando con creadores y managers. Me interesa mucho cómo trabaja [empresa] con creadores y me encantaría sumarte a mi red. ¡Gracias!"}, {"t": "p", "text": "Cambiá [nombre] y [empresa]. Si sabés algo puntual de esa persona o de una campaña de su marca, sumalo: sube mucho la tasa de respuesta."}]'::jsonb, false),
('w4-02', 4, 2, 'Postular a 3 búsquedas abiertas', 'LinkedIn, Bumeran o la web de la empresa', '[{"items": ["Buscá en LinkedIn Empleos, Bumeran y la web de carreras de cada empresa del mapa.", "Términos que sirven: Influencer Marketing, Creator Partnerships, Social Media, Brand Partnerships, Marketing Specialist.", "Filtrá por Argentina o remoto con horario argentino. Descartá las que piden horario de México o EE.UU.", "Adjuntá siempre el CV en PDF, nunca el Word.", "Cargá cada una en Postulaciones como \"Enviada\", con el link del aviso."], "t": "steps"}, {"t": "p", "text": "Tres buenas postulaciones valen más que diez genéricas. Si el aviso pide algo que no tenés, postulate igual si cumplís el 70%."}]'::jsonb, false),
('w4-03', 4, 3, 'Publicar un post en LinkedIn sobre negociación con creadores', 'Un aprendizaje concreto, sin datos de clientes', '[{"t": "p", "text": "Un post te hace visible para la gente del mapa antes de que le escribas. No hace falta que sea largo."}, {"items": ["Primera línea que enganche: una idea concreta, no \"Hoy quiero compartir\".", "Un aprendizaje real de negociar con creadores o managers.", "Cierre con una pregunta o una opinión."], "t": "steps"}, {"label": "Idea para arrancar", "t": "copy", "text": "Después de negociar más de 50 campañas con creadores, aprendí que el mejor cierre no es el más barato: es el que el creador defiende con ganas cuando publica."}, {"t": "p", "text": "Nunca montos ni datos de clientes. Hablá del cómo, no del cuánto."}]'::jsonb, false),
('w5-01', 5, 1, 'Escribirle a 5 personas nuevas del mapa', null, '[{"items": ["Elegí 5 personas de Contactos que estén en \"Por contactar\".", "Mandales solicitud de conexión en LinkedIn con una nota (máximo 300 caracteres).", "Cambiá su estado a \"Contactado\" en el tablero."], "t": "steps"}, {"label": "Nota de conexión", "t": "copy", "text": "Hola [nombre], trabajo en influencer marketing para marcas como Rexona y PepsiCo, negociando con creadores y managers. Me interesa mucho cómo trabaja [empresa] con creadores y me encantaría sumarte a mi red. ¡Gracias!"}, {"t": "p", "text": "Cambiá [nombre] y [empresa]. Si sabés algo puntual de esa persona o de una campaña de su marca, sumalo: sube mucho la tasa de respuesta."}]'::jsonb, false),
('w5-02', 5, 2, 'Postular a 3 búsquedas abiertas', null, '[{"items": ["Buscá en LinkedIn Empleos, Bumeran y la web de carreras de cada empresa del mapa.", "Términos que sirven: Influencer Marketing, Creator Partnerships, Social Media, Brand Partnerships, Marketing Specialist.", "Filtrá por Argentina o remoto con horario argentino. Descartá las que piden horario de México o EE.UU.", "Adjuntá siempre el CV en PDF, nunca el Word.", "Cargá cada una en Postulaciones como \"Enviada\", con el link del aviso."], "t": "steps"}, {"t": "p", "text": "Tres buenas postulaciones valen más que diez genéricas. Si el aviso pide algo que no tenés, postulate igual si cumplís el 70%."}]'::jsonb, false),
('w5-03', 5, 3, 'Hacer seguimiento a los mensajes sin respuesta', 'Una sola vez, a los 7 días', '[{"t": "p", "text": "Un solo seguimiento, a los 7 días del primer mensaje. Más que eso se lee como insistencia."}, {"label": "Mensaje de seguimiento", "t": "copy", "text": "Hola [nombre], te escribo de nuevo por si se perdió mi mensaje. Me encantaría conocer cómo trabaja el equipo de [empresa] con creadores; si en algún momento tenés 15 minutos, me sumaría mucho. ¡Gracias!"}, {"t": "p", "text": "Si después de esto no responde, dejala en \"Contactado\" y seguí con otras personas."}]'::jsonb, false),
('w6-01', 6, 1, 'Escribirle a 5 personas nuevas del mapa', null, '[{"items": ["Elegí 5 personas de Contactos que estén en \"Por contactar\".", "Mandales solicitud de conexión en LinkedIn con una nota (máximo 300 caracteres).", "Cambiá su estado a \"Contactado\" en el tablero."], "t": "steps"}, {"label": "Nota de conexión", "t": "copy", "text": "Hola [nombre], trabajo en influencer marketing para marcas como Rexona y PepsiCo, negociando con creadores y managers. Me interesa mucho cómo trabaja [empresa] con creadores y me encantaría sumarte a mi red. ¡Gracias!"}, {"t": "p", "text": "Cambiá [nombre] y [empresa]. Si sabés algo puntual de esa persona o de una campaña de su marca, sumalo: sube mucho la tasa de respuesta."}]'::jsonb, false),
('w6-02', 6, 2, 'Postular a 3 búsquedas abiertas', null, '[{"items": ["Buscá en LinkedIn Empleos, Bumeran y la web de carreras de cada empresa del mapa.", "Términos que sirven: Influencer Marketing, Creator Partnerships, Social Media, Brand Partnerships, Marketing Specialist.", "Filtrá por Argentina o remoto con horario argentino. Descartá las que piden horario de México o EE.UU.", "Adjuntá siempre el CV en PDF, nunca el Word.", "Cargá cada una en Postulaciones como \"Enviada\", con el link del aviso."], "t": "steps"}, {"t": "p", "text": "Tres buenas postulaciones valen más que diez genéricas. Si el aviso pide algo que no tenés, postulate igual si cumplís el 70%."}]'::jsonb, false),
('w6-03', 6, 3, 'Preparar las respuestas de entrevista', 'Contar el caso del 24% de ahorro en 2 minutos', '[{"t": "p", "text": "Tu mejor carta es el caso de la negociación. Practicalo en voz alta hasta que te salga en 2 minutos."}, {"items": ["Contexto: la campaña, la marca y el presupuesto.", "Problema: la cotización inicial de MXN 250.000.", "Qué hiciste: cómo negociaste con el creador o el manager.", "Resultado: MXN 190.000, un 24% de ahorro, y qué se hizo con esa plata."], "t": "steps"}, {"items": ["¿Por qué te querés ir de tu trabajo actual?", "¿Cómo elegís un creador para una campaña?", "Contame una negociación que salió mal.", "¿Cómo medís si una campaña funcionó?", "¿Cuál es tu expectativa salarial?"], "t": "list"}]'::jsonb, false),
('w7-01', 7, 1, 'Escribirle a 5 personas nuevas del mapa', null, '[{"items": ["Elegí 5 personas de Contactos que estén en \"Por contactar\".", "Mandales solicitud de conexión en LinkedIn con una nota (máximo 300 caracteres).", "Cambiá su estado a \"Contactado\" en el tablero."], "t": "steps"}, {"label": "Nota de conexión", "t": "copy", "text": "Hola [nombre], trabajo en influencer marketing para marcas como Rexona y PepsiCo, negociando con creadores y managers. Me interesa mucho cómo trabaja [empresa] con creadores y me encantaría sumarte a mi red. ¡Gracias!"}, {"t": "p", "text": "Cambiá [nombre] y [empresa]. Si sabés algo puntual de esa persona o de una campaña de su marca, sumalo: sube mucho la tasa de respuesta."}]'::jsonb, false),
('w7-02', 7, 2, 'Postular a 3 búsquedas abiertas', null, '[{"items": ["Buscá en LinkedIn Empleos, Bumeran y la web de carreras de cada empresa del mapa.", "Términos que sirven: Influencer Marketing, Creator Partnerships, Social Media, Brand Partnerships, Marketing Specialist.", "Filtrá por Argentina o remoto con horario argentino. Descartá las que piden horario de México o EE.UU.", "Adjuntá siempre el CV en PDF, nunca el Word.", "Cargá cada una en Postulaciones como \"Enviada\", con el link del aviso."], "t": "steps"}, {"t": "p", "text": "Tres buenas postulaciones valen más que diez genéricas. Si el aviso pide algo que no tenés, postulate igual si cumplís el 70%."}]'::jsonb, false),
('w7-03', 7, 3, 'Definir su piso y sus condiciones no negociables', 'Sueldo, horario, relación de dependencia, proyección', '[{"t": "p", "text": "Antes de que llegue una oferta, tenés que saber qué aceptás y qué no. Si lo definís después, decide la ansiedad."}, {"items": ["Sueldo mínimo en bruto por el que aceptarías.", "Horario: hasta qué hora estás dispuesto a trabajar.", "Modalidad: presencial, híbrido o remoto.", "Relación de dependencia, obra social y aportes.", "Proyección: qué puesto podrías tener en 2 años."], "t": "list"}, {"t": "p", "text": "Anotalo y pasáselo a Karen para sumarlo al tablero."}]'::jsonb, false),
('w8-01', 8, 1, 'Revisar qué canal dio más respuestas', 'Contactos directos vs. postulaciones', '[{"t": "p", "text": "Mirá los números de arriba del tablero y compará los dos caminos."}, {"items": ["Contactos directos: cuántos respondieron (tasa de respuesta).", "Postulaciones: cuántas pasaron a Entrevista.", "Qué tipo de empresa respondió más: marcas o agencias."], "t": "list"}]'::jsonb, false),
('w8-02', 8, 2, 'Ajustar el plan para las próximas 8 semanas', null, '[{"t": "p", "text": "Con lo que funcionó y lo que no, Karen arma con Claude las tareas de las semanas 9 a 16."}, {"t": "p", "text": "Pensá antes qué te costó más y qué te gustaría hacer distinto."}]'::jsonb, false),
('w2-05', 2, 5, 'Crear un mail solo para la búsqueda', 'Para que las alertas de empleo no se mezclen con tu mail personal', '[{"t": "p", "text": "Todas las alertas de los portales van a llegar acá. Separado de tu mail personal, nada se pierde y el tablero puede leerlo sin tocar tus mails privados."}, {"t": "steps", "items": ["Creá una cuenta nueva de Gmail, por ejemplo nombre.apellido.busqueda@gmail.com.", "Usá ese mail solo para registrarte en portales y alertas.", "Pasale la dirección a Karen: es la que va a conectar con la sección News del tablero."]}]'::jsonb, false),
('w2-06', 2, 6, 'Activar alertas de empleo en los portales', 'LinkedIn, Computrabajo, Bumeran y Zonajobs, al mail nuevo', '[{"t": "p", "text": "Cada portal te avisa por mail cuando aparece un aviso que coincide con tu búsqueda. Esos mails alimentan la sección News."}, {"t": "steps", "items": ["En cada portal, iniciá sesión con el mail nuevo.", "Hacé una búsqueda con cada término de abajo, filtrando por Buenos Aires o remoto.", "Guardala como alerta con frecuencia diaria.", "En LinkedIn, revisá en la configuración de notificaciones que las alertas vayan por mail y no solo al celular."]}, {"t": "copy", "label": "Términos de búsqueda", "text": "Influencer Marketing\nCreator Partnerships\nBrand Partnerships\nTalent Manager\nSocial Media Specialist\nMarketing Specialist"}, {"t": "p", "text": "Con 4 o 5 alertas por portal alcanza. Más que eso llena el mail de avisos que no van."}]'::jsonb, false)
